package me.minis.ledger;
import android.app.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
/** Local dialog styling; no external UI dependency or theme-colour surprises. */
public final class LightDialog {
 private static int dp(Activity a,int n){return Math.round(a.getResources().getDisplayMetrics().density*n);}
 private static GradientDrawable bg(int color,int radius,Activity a){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(a,radius));return g;}
 public static Dialog show(Activity a,String title,String message,String positive,String negative,boolean danger,Runnable yes,Runnable no){
  boolean dark=LedgerDb.prefs(a).getString("theme","light").equals("dark");Dialog d=new Dialog(a);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(a,22),dp(a,24),dp(a,22),dp(a,20));panel.setBackground(bg(AppAppearance.surface(dark),24,a));
  TextView heading=new TextView(a);heading.setText(title);heading.setTextSize(19);heading.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));heading.setTextColor(AppAppearance.text(dark));panel.addView(heading);
  ScrollView scroll=new ScrollView(a);TextView body=new TextView(a);body.setText(message);body.setTextSize(14);body.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));body.setTextColor(AppAppearance.muted(dark));body.setLineSpacing(dp(a,5),1);body.setPadding(0,dp(a,12),0,dp(a,20));scroll.addView(body);int max=Math.max(dp(a,90),a.getResources().getDisplayMetrics().heightPixels/3);body.measure(View.MeasureSpec.makeMeasureSpec(a.getResources().getDisplayMetrics().widthPixels-dp(a,88),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));panel.addView(scroll,new LinearLayout.LayoutParams(-1,Math.min(max,body.getMeasuredHeight())));
  LinearLayout row=new LinearLayout(a);row.setOrientation(LinearLayout.HORIZONTAL);Button cancel=button(a,negative,AppAppearance.soft(dark),AppAppearance.muted(dark));Button ok=button(a,positive,danger?0xffbe6679:0xff626ddd,Color.WHITE);LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,dp(a,46),1);left.setMargins(0,0,dp(a,10),0);row.addView(cancel,left);row.addView(ok,new LinearLayout.LayoutParams(0,dp(a,46),1));panel.addView(row);d.setContentView(panel);d.setCanceledOnTouchOutside(true);d.setOnCancelListener(x->{if(no!=null)no.run();});cancel.setOnClickListener(v->{d.dismiss();if(no!=null)no.run();});ok.setOnClickListener(v->{d.dismiss();if(yes!=null)yes.run();});d.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout(Math.min(a.getResources().getDisplayMetrics().widthPixels-dp(a,40),dp(a,380)),-2);WindowManager.LayoutParams p=w.getAttributes();p.dimAmount=.23f;p.gravity=Gravity.CENTER;w.setAttributes(p);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);}return d;
 }
 public static Dialog content(Activity a,String title,View content,String positive,String negative,Runnable yes){boolean dark=LedgerDb.prefs(a).getString("theme","light").equals("dark");Dialog d=new Dialog(a);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=new LinearLayout(a);panel.setOrientation(1);panel.setPadding(dp(a,20),dp(a,22),dp(a,20),dp(a,18));panel.setBackground(bg(AppAppearance.surface(dark),24,a));TextView heading=new TextView(a);heading.setText(title);heading.setTextSize(19);heading.setTextColor(AppAppearance.text(dark));panel.addView(heading);ScrollView scroll=new ScrollView(a);scroll.addView(content);panel.addView(scroll,new LinearLayout.LayoutParams(-1,Math.min(dp(a,280),a.getResources().getDisplayMetrics().heightPixels/2)));LinearLayout row=new LinearLayout(a);Button cancel=button(a,negative,AppAppearance.soft(dark),AppAppearance.muted(dark)),ok=button(a,positive,0xff626ddd,Color.WHITE);LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,dp(a,46),1);left.setMargins(0,dp(a,12),dp(a,8),0);row.addView(cancel,left);LinearLayout.LayoutParams right=new LinearLayout.LayoutParams(0,dp(a,46),1);right.topMargin=dp(a,12);row.addView(ok,right);panel.addView(row);d.setContentView(panel);d.setCanceledOnTouchOutside(true);cancel.setOnClickListener(v->d.dismiss());ok.setOnClickListener(v->{d.dismiss();if(yes!=null)yes.run();});Window w=d.getWindow();if(w!=null)w.addFlags(WindowManager.LayoutParams.FLAG_SECURE);d.show();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout(Math.min(a.getResources().getDisplayMetrics().widthPixels-dp(a,40),dp(a,400)),-2);}return d;}
 private static Button button(Activity a,String label,int background,int text){Button b=new Button(a);b.setText(label);b.setTextSize(14);b.setAllCaps(false);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setTextColor(text);b.setBackground(bg(background,13,a));b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(0,0,0,0);return b;}
}
